    charts = pickle.load(f)

# Pre-compute all stats for the report
# Cities present
cities_present = sorted(df['city'].unique())  # 7 cities

# Overview
overview = df.groupby('city').agg(
    total_listings=('id', 'count'),
    listings_with_price=('price', lambda x: x.notna().sum()),
    listings_without_price=('price', lambda x: x.isna().sum()),
    median_price=('price', 'median'),
    mean_price=('price', 'mean'),
    std_price=('price', 'std'),
    min_price=('price', 'min'),
    max_price=('price', 'max'),
).round(2)

# Room type
rt = df.groupby(['city', 'room_type']).size().unstack(fill_value=0)
rt_pct = rt.div(rt.sum(axis=1), axis=0) * 100
entire_home_share = rt_pct['Entire home/apt'].round(1)

# Professional hosts
prof_share = df.groupby('city')['calculated_host_listings_count'].apply(lambda x: (x >= 5).mean() * 100).round(1)
super_prof_share = df.groupby('city')['calculated_host_listings_count'].apply(lambda x: (x >= 20).mean() * 100).round(1)

# Demand
demand = df.groupby('city').agg(
    avg_reviews_per_month=('reviews_per_month', 'mean'),
    median_reviews_per_month=('reviews_per_month', 'median'),
    avg_total_reviews=('number_of_reviews', 'mean'),
    avg_reviews_ltm=('number_of_reviews_ltm', 'mean'),
    pct_no_reviews=('number_of_reviews', lambda x: (x == 0).mean() * 100),
    pct_reviewed_ltm=('number_of_reviews_ltm', lambda x: (x > 0).mean() * 100),
).round(2)

# Availability
avail = df.groupby('city').agg(
    mean_availability=('availability_365', 'mean'),
    median_availability=('availability_365', 'median'),
    mean_min_nights=('minimum_nights', 'mean'),
    median_min_nights=('minimum_nights', 'median'),
    pct_min_nights_30plus=('minimum_nights', lambda x: (x >= 30).mean() * 100),
    pct_min_nights_7plus=('minimum_nights', lambda x: (x >= 7).mean() * 100),
    pct_zero_availability=('availability_365', lambda x: (x == 0).mean() * 100),
    pct_high_availability=('availability_365', lambda x: (x > 300).mean() * 100),
).round(2)

# Price by room type
df_price = df[df['price'].notna()]
price_room_med = df_price.groupby(['city', 'room_type'])['price'].median().unstack().round(0)
price_room_mean = df_price.groupby(['city', 'room_type'])['price'].mean().unstack().round(0)
